mapper.select:
SELECT COUNT(*)
FROM warehouse
WHERE company_id = #{companyId}
AND warehouse_id = #{warehouseId}

SELECT COUNT(*)
FROM product
WHERE company_id = #{companyId}
AND product_id = #{productId}
AND use_yn = 'Y'

SELECT lot_managed_yn
FROM product
WHERE company_id = #{companyId}
AND product_id = #{productId}
AND use_yn = 'Y'

SELECT COUNT(*)
FROM lot
WHERE company_id = #{companyId}
AND product_id = #{productId}
AND lot_id = #{lotId}

SELECT quantity
FROM stock
WHERE company_id = #{companyId}
AND warehouse_id = #{warehouseId}
AND product_id = #{productId}

SELECT ls.quantity
FROM lot_stock ls
JOIN lot l
ON l.lot_id = ls.lot_id
WHERE ls.company_id = #{companyId}
AND ls.warehouse_id = #{warehouseId}
AND l.product_id = #{productId}
AND ls.lot_id = #{lotId}
